#!/usr/bin/env node
import fs from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath, pathToFileURL} from 'node:url';
import {compile, TARGETS} from '../src/build.mjs';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const HELP = `GPT with Taste — deterministic local build
  node scripts/build.mjs [--check] [--target <id>]...
Targets: ${TARGETS.join(', ')} (default: all)
--check compares generated bytes without writing. Edit recipe/ to change behavior.
`;

export async function run(args = process.argv.slice(2), root = ROOT) {
  let check = false;
  const targets = [];
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--check') check = true;
    else if (args[i] === '--target') {
      if (!args[i + 1] || args[i + 1].startsWith('--')) throw new Error('--target requires an id');
      targets.push(args[++i]);
    } else if (args[i] === '--help' || args[i] === '-h') { console.log(HELP); return; }
    else throw new Error(`Unknown argument: ${args[i]}`);
  }
  const outputs = await compile(root, targets.length ? targets : undefined);
  const drift = [];
  for (const [relative, value] of outputs) {
    const file = path.join(root, relative), expected = Buffer.from(value);
    let current;
    try { current = await fs.readFile(file); }
    catch (error) { if (error.code !== 'ENOENT') throw error; }
    if (current?.equals(expected)) continue;
    if (check) drift.push(relative);
    else {
      await fs.mkdir(path.dirname(file), {recursive: true});
      await fs.writeFile(file, expected);
    }
  }
  if (drift.length) throw new Error(`Generated files have drifted:\n${drift.map(file => `  ${file}`).join('\n')}\nRun node scripts/build.mjs to rebuild.`);
  console.log(`${check ? 'Checked' : 'Built'} ${outputs.size} generated files (${[...new Set(targets.length ? targets : TARGETS)].sort().join(', ')}).`);
  return outputs;
}

if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href)
  run().catch(error => { console.error(`GPT with Taste build: ${error.message}`); process.exitCode = 1; });
